                    field1 = "(" + field1 + " as " + joinfield.JoinCastType + " ) ";
                }
                DataSourceFields prevjoin = prevjoinfields.Where(a => a.JoinFieldId.ToLower() == joinfield.Id.ToString().ToLower()).FirstOrDefault();
                Fields myprevfield = _context.Fields.FirstOrDefault(a => a.Id.ToString() == prevjoin.FieldId);
                if (prevjoin == null)
                {
                    prevjoin = prevjoinfields.Where(a => a.JoinFieldId2.ToLower() == joinfield.Id.ToString().ToLower()).FirstOrDefault();
                    jointype = joinfield.JoinType2;
                    myprevfield = _context.Fields.FirstOrDefault(a => a.Id.ToString() == prevjoin.FieldId);
                    if (joinfield.JoinCastType2 != "" && joinfield.JoinCastType2 != "null")
                    {
                        field1 = "(" + field1 + " as " + joinfield.JoinCastType2 + " ) ";
                    }
                }
                string field2 = "[dbo].[" + prevEntity.SysName + "].[" + myprevfield.SystemName + "] ";

                if (prevjoin.JoinEntityId == myentity.Id.ToString().ToLower())
                {
                    if (prevjoin.JoinCastType != "" && prevjoin.JoinCastType != null)
                    {
                        field2 += "(" + field2 + " as " + prevjoin.JoinCastType + " ) ";
                    }

                }
                if (prevjoin.JoinEntityId2 == myentity.Id.ToString().ToLower())
                {
                    if (prevjoin.JoinCastType2 != "" && prevjoin.JoinCastType2 != null)
                    {
                        field2 += "(" + field2 + " as " + prevjoin.JoinCastType2 + " ) ";
                    }

                }
                if (and)
                    from += " AND ";
                and = true;
                from += field1 + jointype + field2;

            }
        }
        else
        {
            if (from != "")
                from += " AND ";
